insert into public.blog_posts (
  title, slug, excerpt, content_html, cover_image, status, published_at, category, tags, related_product_ids
) values
(
  'Automatique ou Quartz : Bien choisir son garde-temps', 'choisir-montre-automatique-ou-quartz', 'La distinction entre montre mécanique automatique et calibre à quartz ne se résume pas à une question de prix. Elle touche au rapport que vous entretenez avec l''objet, à son autonomie et à sa vocation de transmission patrimoniale.', '<h2>Le mouvement automatique : l''énergie vivante du geste</h2><p>Une montre automatique tire son énergie des mouvements naturels de votre poignet. Une masse oscillante (le rotor), visible au travers du fond transparent de pièces d''exception comme la Tissot Le Locle, remonte en continu le ressort de barillet.</p><p>Avec des calibres modernes comme le Powermatic 80, la réserve de marche atteint 80 heures. Vous pouvez déposer la montre le vendredi soir et la retrouver le lundi matin parfaitement à l''heure sans intervention.</p><p>Choisir une automatique, c''est choisir un objet vivant et intemporel. Elle ne nécessite aucune pile : entretenue tous les cinq ans, elle traverse les décennies et se transmet naturellement de génération en génération.</p><h2>Le calibre à quartz : la précision absolue et l''immédiateté</h2><p>Une montre à quartz utilise la vibration régulière d''un cristal de quartz sous l''impulsion d''une pile électrique pour cadencer le temps avec une précision rigoureuse de quelques secondes par an.</p><p>C''est le choix privilégié pour une montre sportive, un chronographe d''intervention ou une pièce active. Vous la posez, vous la reprenez après plusieurs semaines, et la trotteuse bat la mesure avec une ponctualité infaillible.</p><p>La pile se remplace simplement tous les deux à trois ans lors d''un contrôle d''étanchéité réalisé par nos soins à Abidjan.</p><h2>Quel choix pour votre prochaine acquisition ?</h2><p>Si votre souhait est d''acquérir une création noble marquant un accomplissement personnel ou destinée à être léguée, le mouvement automatique offre une poésie et une dimension artisanale uniques.</p><p>Si vous cherchez un instrument quotidien, robuste et immédiatement opérationnel en toutes circonstances à Abidjan, un calibre quartz suisse de manufacture répondra à votre exigence.</p>', '/assets/products/le-locle-caseback.jpg',
  'published', now(), 'Horlogerie', '[]'::jsonb, '["prod-tissot-le-locle-20th"]'::jsonb
),
(
  'L''Art du Sillage : Bien porter son parfum sous le climat d''Abidjan', 'art-du-parfum-sublimer-son-sillage-a-abidjan', 'Sous le climat chaud et humide d''Abidjan, les fragrances réagissent avec intensité. Découvrez les secrets pour choisir entre Eau de Parfum et Extrait, et faire rayonner votre signature olfactive avec subtilité.', '<h2>Comprendre l''évaporation des essences sous la chaleur</h2><p>La température corporelle et l''hygrométrie accélèrent la diffusion des molécules odorantes de tête (agrumes, bergamote, notes ozoniques). Celles-ci s''expriment avec éclat mais s''estompent plus rapidement.</p><p>Pour conserver une aura sophistiquée tout au long de la journée, privilégiez des compositions dotées d''un cœur floral noble (jasmin, néroli, iris) et d''un fond boisé ou ambré (oud, santal, fève tonka, musc blanc) qui se fixent idéalement sur l''épiderme.</p><h2>Eau de Parfum vs Extrait : la juste concentration</h2><p>L''Eau de Parfum offre un équilibre parfait entre fraîcheur d''ouverture et rémanence au bureau ou lors de vos rendez-vous d''affaires au Plateau ou à Cocody.</p><p>Pour les grandes réceptions ou les dîners mondains, les Extraits de Parfum et les élixirs rares délivrent une concentration supérieure à 25%, libérant une signature envoûtante sans jamais être entêtante.</p><h2>Les zones de diffusion stratégiques</h2><p>Vaporisez sur les points de pulsation : l''intérieur des poignets, les creux des clavicules et derrière les oreilles. Pour une élégance absolue sans altérer vos étoffes précieuses, un nuage léger au revers de votre veste assure un sillage mémorable.</p>', '/assets/products/seastar-wrist.jpg',
  'published', now(), 'Haute Parfumerie', '[]'::jsonb, '[]'::jsonb
),
(
  'Lunettes Solaires de Créateur : Allier Haute Protection UV et Allure', 'guide-lunettes-de-soleil-createur-protection-et-style', 'Au-delà d''un accessoire de style incontournable, une monture de luxe solaire à Abidjan est un bouclier indispensable contre le rayonnement solaire intense. Repères de style et d''ergonomie.', '<h2>Indice de protection et verres polarisés</h2><p>À proximité de la lagune Ébrié et du littoral de Grand-Bassam ou Assinie, la réverbération de la lumière est particulièrement forte. Des verres solaires de catégorie 3 dotés d''un filtre polarisant éliminent les reflets parasites et améliorent les contrastes sans assombrir la vue.</p><p>Toutes nos montures solaires répondent aux normes strictes de filtration 100% UVA et UVB pour préserver votre santé visuelle.</p><h2>Morphologie et architecture des montures</h2><p>Les visages ovales profitent d''une liberté totale de formes, des modèles pilotes aviateur aux silhouettes géométriques contemporaines.</p><p>Pour un visage rond ou carré, les formes pantos, hexagonales ou rectangulaires adoucissent les traits et structurent le port de tête avec une élégance naturelle.</p><p>L''acétate de cellulose de haute densité et le titane poli garantissent une légèreté exceptionnelle au porter, même pendant les heures les plus chaudes.</p><h2>L''accord parfait entre lunettes, montre et accessoires</h2><p>Harmonisez les métaux : une monture aux accents dorés ou or rose dialoguera idéalement avec le boîtier bicolore de votre garde-temps. Pour un look contemporain et épuré, l''acétate noir profond s''associe avec un bracelet en acier 316L.</p>', '/assets/products/pr516-chronograph.jpg',
  'published', now(), 'Lunetterie de Luxe', '[]'::jsonb, '[]'::jsonb
)
on conflict (slug) do update set
  title = excluded.title, excerpt = excluded.excerpt, content_html = excluded.content_html,
  cover_image = excluded.cover_image, status = excluded.status, published_at = excluded.published_at,
  category = excluded.category, tags = excluded.tags, related_product_ids = excluded.related_product_ids;

